package com.gameaggregator.incidentservice.application;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.incidentservice.api.IncidentDtos.*;import com.gameaggregator.incidentservice.domain.*;import com.gameaggregator.incidentservice.infrastructure.*;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class IncidentService{final IncidentRepository incidents;final IncidentAffectedServiceRepository affected;final IncidentTimelineRepository timeline;public IncidentService(IncidentRepository i,IncidentAffectedServiceRepository a,IncidentTimelineRepository t){incidents=i;affected=a;timeline=t;}public Incident create(Create r){var i=incidents.save(new Incident(r.incidentNumber(),r.title(),r.description(),r.severity(),r.assigneeId(),r.relatedDeploymentId()));r.affectedServices().forEach(s->affected.save(new IncidentAffectedService(i.id,s)));event(i.id,r.actorId(),"CREATED","Incident created");return i;}public Incident get(UUID id){return incidents.findById(id).orElseThrow(()->new NotFoundException("INCIDENT_NOT_FOUND","Incident was not found"));}public List<Incident> list(){return incidents.findAll();}public Incident acknowledge(UUID id,Actor r){var i=get(id);require(i,"OPEN");i.status="ACKNOWLEDGED";i.acknowledgedAt=Instant.now();event(id,r.actorId(),"ACKNOWLEDGED",r.message());return i;}public Incident assign(UUID id,Assign r){var i=get(id);i.assigneeId=r.assigneeId();event(id,r.actorId(),"ASSIGNED","Assigned to "+r.assigneeId());return i;}public Incident resolve(UUID id,Actor r){var i=get(id);if(!Set.of("OPEN","ACKNOWLEDGED").contains(i.status))throw new IllegalStateException("Incident cannot be resolved from "+i.status);i.status="RESOLVED";i.resolvedAt=Instant.now();event(id,r.actorId(),"RESOLVED",r.message());return i;}public Incident postmortem(UUID id,Postmortem r){var i=get(id);if(!"RESOLVED".equals(i.status))throw new IllegalStateException("Resolve incident before postmortem");i.postmortem=r.content();i.status="CLOSED";event(id,r.actorId(),"POSTMORTEM",r.content());return i;}public IncidentTimeline add(UUID id,Timeline r){get(id);return event(id,r.actorId(),r.type(),r.message());}public List<IncidentTimeline> timeline(UUID id){get(id);return timeline.findAllByIncidentIdOrderByCreatedAtAsc(id);}private IncidentTimeline event(UUID id,UUID actor,String type,String msg){return timeline.save(new IncidentTimeline(id,actor,type,msg==null?type:msg));}private void require(Incident i,String s){if(!s.equals(i.status))throw new IllegalStateException("Incident must be "+s);}}